use super::*;
use dm_preprocess::{AcquiredSource,SourceProvider,SourceText};
use std::path::Path;
#[path="../examples/support/reference_hierarchy.rs"]mod reference_hierarchy;
struct Source(AcquiredSource);
impl SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Err("actual original acquisition required".into())}fn acquired_source(&self,_:&Path)->Result<Option<AcquiredSource>,String>{Ok(Some(self.0.clone()))}fn source_acquisition(&self,_:&Path,text:&SourceText)->Option<AcquiredSource>{self.0.lease().source_text().same_view(text).then(||self.0.clone())}}
fn frontend(source:&str)->dm_tree::frontend::ColdFrontend{let seed=reference_hierarchy::seed();dm_tree::frontend::build_with_config(Path::new("original-group.dme"),&Source(AcquiredSource::from_original_bytes(source.as_bytes().to_vec(),())),&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(&seed),observer:None}).unwrap()}
#[test]fn original_mixed_group_projects_actual_formal_before_builtin_and_implicit_after_builtin(){for(source,formal)in[("/proc/abs(alpha)\n    return alpha\n",true),("/abs(alpha)\n    return alpha\n",false)]{let front=frontend(source);let tree=&*front.snapshot.tree;let profile=tree.checker_builtin_profile().unwrap();let group=Group::issue(tree,profile,SymbolId::of("/"),SymbolId::of("abs")).unwrap();assert_eq!(group.len().unwrap(),2);let source=group.source(0).unwrap().0;let source_target=EffectTarget::Source(source);let member=tree.resolve(tree.lookup_type(source.owner).unwrap(),source.name,if source.verb{MemberKind::Verb}else{MemberKind::Proc}).unwrap();let actual_parent=crate::checks_parent_call::parent_fact_in_profile(tree,member,tree,Some(profile)).unwrap();assert_eq!(actual_parent.has_parent,!formal);assert_eq!(actual_parent.display,format!("/proc/abs[{}/2]",usize::from(!formal)));let builtin=EffectTarget::Builtin(group.builtin.as_ref().unwrap().0);assert_eq!(group.coordinates(source_target).unwrap(),(usize::from(!formal),2));assert_eq!(group.coordinates(builtin).unwrap(),(usize::from(formal),2));let winner=crate::checker_call_facts::callable_any(tree,tree,profile,source.owner,source.name).unwrap();assert_eq!(crate::checker_effects::callable_target(tree,profile,&winner).unwrap(),if formal{builtin}else{source_target});let later=if formal{builtin}else{source_target};let earlier=if formal{source_target}else{builtin};assert_eq!(group.parent(later,tree).unwrap(),Some(earlier));assert_eq!(group.parent(earlier,tree).unwrap(),None);let display=crate::checker_callable_display::original::<String>(tree,source,|_|Ok(()),||Ok(())).unwrap().to_string();assert_eq!(display,format!("/proc/abs[{}/2]",usize::from(!formal)));let display=crate::checker_callable_display::builtin::<String>(tree,group.builtin.as_ref().unwrap().0,||Ok(())).unwrap().to_string();assert_eq!(display,format!("/proc/abs[{}/2]",usize::from(formal)));crate::checker_call_facts::require_original_group_chronology(tree,profile,&group.fact(source_target).unwrap(),"abs").unwrap();crate::checker_call_facts::require_original_group_chronology(tree,profile,&group.fact(builtin).unwrap(),"abs").unwrap();let foreign=frontend("/proc/other()\n    return\n");assert!(group.parent(later,&*foreign.snapshot.tree).unwrap_err().contains("foreign"));}}
#[test]fn actual_fixed_catalog_has_at_most_one_value_per_unified_callable_group(){let catalog=dm_tree::checker_builtins::pinned_catalog().unwrap();for row in catalog.declarations.iter().filter(|row|matches!(row.kind,MemberKind::Proc|MemberKind::Verb)){assert_eq!(catalog.declarations.iter().filter(|other|other.owner==row.owner&&other.name==row.name&&matches!(other.kind,MemberKind::Proc|MemberKind::Verb)).count(),1,"actual fixed group {:?}/{:?}",row.owner,row.name);}}

#[test]fn original_mixed_group_checks_each_new_source_hop_and_preserves_typed_control_failure(){use crate::policy_body_demand::PolicyFailure;let mut text=String::new();for i in 0..48{text.push_str(&format!("/abs(arg{i})\n    return arg{i}\n"));}let front=frontend(&text);let tree=&*front.snapshot.tree;let profile=tree.checker_builtin_profile().unwrap();let polls=std::cell::Cell::new(0usize);let error=Group::issue_using(tree,profile,SymbolId::of("/"),SymbolId::of("abs"),&mut||{let next=polls.get()+1;polls.set(next);if next==12{Err(PolicyFailure::Operational(std::io::Error::from_raw_os_error(1450)))}else{Ok(())}}).err().unwrap();assert_eq!(polls.get(),12);assert!(matches!(error,PolicyFailure::Operational(actual)if actual.raw_os_error()==Some(1450)));let group=Group::issue(tree,profile,SymbolId::of("/"),SymbolId::of("abs")).unwrap();let first=EffectTarget::Source(group.source(0).unwrap().0);let polls=std::cell::Cell::new(0usize);let result=group.coordinates_using(first,&mut||{let next=polls.get()+1;polls.set(next);if next==5{Err(PolicyFailure::Operational(std::io::Error::new(std::io::ErrorKind::Interrupted,"actual coordinate walk control")))}else{Ok(())}});assert_eq!(polls.get(),5);assert!(matches!(result,Err(PolicyFailure::Operational(actual))if actual.kind()==std::io::ErrorKind::Interrupted));assert_eq!(group.coordinates(first).unwrap(),(1,49));}
